  "commands": [
    {
      "keystrokes": "find . -type f -name '*.json' -o -name '*.yaml' -o -name '*.yml' -o -name '*.toml' -o -name '*.cfg' -o -name '*.conf' 2>/dev/null | head -50\\n",
      "duration": 0.5
    },
    {
      "keystrokes": "ls -la .claude/\\n",
      "duration": 0.1
    },
    {
